<template><section><PageHeading eyebrow="MOMENTS BEYOND WORDS" title="媒体库" description="图片、文件、声音，以及文字之外的那些瞬间。"><div class="segment-control" aria-label="媒体时间范围"><button v-for="d in [7,30,90]" :key="d" :class="{active:days===d}" :aria-pressed="days===d" @click="days=d">{{ d }} 天</button></div><button class="btn" :disabled="loading" @click="refresh(true)"><UiIcon name="refresh" :size="15"/>刷新媒体</button></PageHeading><SampleNotice :sample="sample"/><div class="toolbar" style="padding:23px 0 17px"><div class="media-tabs"><button v-for="tab in tabs" :key="tab.type" class="btn btn-ghost" :class="{active:type===tab.type}" :aria-pressed="type===tab.type" @click="type=tab.type"><UiIcon :name="tab.icon" :size="15"/>{{ tab.label }}<span class="count">{{ tab.type==='all'?media.length:media.filter(i=>i.type===tab.type).length }}</span></button></div><span class="spacer"/></div><div class="toolbar" style="padding:0 0 23px"><label class="search-field"><UiIcon name="search" :size="16"/><input v-model="query" type="search" placeholder="搜索文件名或发送者" aria-label="搜索媒体"/></label><span class="spacer"/><span class="count-label">{{ filtered.length }} 个去重后的媒体引用</span></div><StatePanel v-if="loading" kind="loading"/><StatePanel v-else-if="error" kind="error" title="媒体档案暂时无法读取" :description="error" @retry="refresh(true)"/><StatePanel v-else-if="!filtered.length" title="这里还没有匹配的媒体" description="切换时间范围或类型；当前仅扫描所示会话样本中的媒体引用。"/><div v-else class="media-grid"><article v-for="item in filtered.slice((page-1)*size,page*size)" :key="item.id" class="media-card"><button class="media-thumb" :aria-label="`预览 ${item.name}`" @click="openPreview(item)"><img v-if="item.type==='image'&&canAutoLoad(item)&&!failed[item.id]" :src="source(item)" :alt="item.name" loading="lazy" referrerpolicy="no-referrer" @error="failed[item.id]=true"/><div v-else class="media-placeholder" :class="item.type"><div v-if="item.type==='voice'" class="waveform"><i v-for="n in 21" :key="n" :style="{height:`${12+(n*13)%43}px`}"/></div><UiIcon v-else :name="item.type" :size="45"/><small v-if="item.type==='image'" style="display:block;margin-top:10px">{{ failed[item.id]?'图片加载失败':'点击预览后加载' }}</small><small v-if="isDemoMissing(item)" style="display:block;margin-top:10px">演示附件</small></div><span class="type-badge"><UiIcon :name="item.type" :size="11"/>{{ labels[item.type] }}</span></button><div class="media-info"><div class="media-title truncate" :title="item.name">{{ item.name }}</div><p style="font-size:10px;color:var(--muted)">{{ item.sender||'未知发送者' }} · {{ formatTime(item.time) }}</p></div><div class="media-card-foot"><span class="count-label">未提供文件大小</span><div style="display:flex;gap:4px"><button class="btn btn-ghost btn-square" :aria-label="`复制 ${item.name} 的链接`" @click="copyText(item.url)"><UiIcon name="link" :size="13"/></button><button class="btn btn-ghost btn-square" :aria-label="`打开 ${item.name} 下载链接`" @click="openFile(item)"><UiIcon name="download" :size="14"/></button></div></div></article></div><UiPager v-if="!error&&!loading" :page="page" :size="size" :total="filtered.length" @change="page=$event"/><UiDialog v-model="previewOpen" :title="selected?.name||'媒体预览'" eyebrow="A MOMENT FROM YOUR ARCHIVE"><template v-if="selected&&previewOpen"><div v-if="isDemoMissing(selected)" class="state-panel"><div class="state-art"><UiIcon :name="selected.type" :size="42"/></div><h3>这是演示附件</h3><p>用于展示文件卡片与预览布局，不包含真实视频、音频或文档。</p></div><div v-else-if="!canAutoLoad(selected)&&!consented" class="state-panel"><h3>加载外部资源？</h3><p>此操作会连接到 {{ host(selected) }}，可能暴露你的 IP 地址。</p><button class="btn btn-primary" style="margin-top:15px" @click="consented=true">允许本次预览</button></div><img v-else-if="selected.type==='image'" class="preview-image" :src="source(selected)" alt="媒体图片预览" referrerpolicy="no-referrer"/><video v-else-if="selected.type==='video'" :src="selected.url" style="width:100%;max-height:60vh" controls preload="metadata"/><audio v-else-if="selected.type==='voice'" :src="selected.url" controls style="width:100%" preload="metadata"/><div v-else class="state-panel"><div class="state-art"><UiIcon name="file" :size="42"/></div><h3>{{ selected.name }}</h3><p>该类型暂不支持内嵌预览，可打开资源链接。</p></div><p class="scope-note">{{ selected.sender }} · {{ formatTime(selected.time) }}</p></template><template #footer><button class="btn" @click="copyText(selected?.url)"><UiIcon name="link" :size="14"/>复制链接</button><button class="btn btn-primary" :disabled="!selected||isDemoMissing(selected)" @click="openFile(selected)"><UiIcon name="download" :size="14"/>打开资源</button></template></UiDialog></section></template>
<script>
import { ref,computed,watch } from 'vue'
import useSample from '@/lib/useSample'
import { extractMedia,typeLabels,formatTime } from '@/lib/data'
import { resolvedApiBase } from '@/api'
import { demoEnabled,assetUrl } from '@/lib/demo'
import { notify,copyText } from '@/lib/workspace'
import PageHeading from '@/components/ui/PageHeading.vue'
import UiIcon from '@/components/ui/UiIcon.vue'
import UiDialog from '@/components/ui/UiDialog.vue'
import UiPager from '@/components/ui/UiPager.vue'
import SampleNotice from '@/components/ui/SampleNotice.vue'
import StatePanel from '@/components/ui/StatePanel.vue'
export default {name:'ArchiveMedia',components:{PageHeading,UiIcon,UiDialog,UiPager,SampleNotice,StatePanel},setup(){const sample=useSample(7),type=ref('all'),query=ref(''),page=ref(1),size=12,previewOpen=ref(false),selected=ref(null),consented=ref(false),failed=ref({});const media=computed(()=>extractMedia(sample.stats.value.logs,resolvedApiBase())),filtered=computed(()=>media.value.filter(i=>(type.value==='all'||i.type===type.value)&&(i.name+' '+i.sender).toLowerCase().includes(query.value.toLowerCase())));watch([type,query,sample.days],()=>{page.value=1});const tabs=[{type:'all',label:'全部',icon:'grid'},{type:'image',label:'图片',icon:'image'},{type:'video',label:'视频',icon:'video'},{type:'voice',label:'语音',icon:'voice'},{type:'file',label:'文件',icon:'file'}];const isDemoMissing=item=>demoEnabled&&new URL(item.url).pathname.startsWith('/demo/'),source=item=>demoEnabled&&new URL(item.url).pathname.startsWith('/brand/')?assetUrl(item.name):item.url,canAutoLoad=item=>demoEnabled&&new URL(item.url).pathname.startsWith('/brand/')||new URL(item.url).origin===new URL(resolvedApiBase()).origin;const openFile=item=>{if(!item)return;if(isDemoMissing(item)){notify('演示附件没有真实文件；接入自己的数据后可打开。');return}if(demoEnabled&&item.type==='image'){openPreview(item);return}window.open(item.url,'_blank','noopener,noreferrer')};const openPreview=item=>{selected.value=item;consented.value=false;previewOpen.value=true};return {...sample,type,query,page,size,previewOpen,selected,consented,failed,media,filtered,tabs,isDemoMissing,source,canAutoLoad,openFile,openPreview,copyText,formatTime,labels:typeLabels,host:item=>new URL(item.url).host}}}
</script>
